window.CODE = Object.assign(window.CODE || {}, {"ch16/claude_desktop_config.json":"{\n  \"mcpServers\": {\n    \"city-clinic\": {\n      \"command\": \"/full/path/to/venv/bin/python\",\n      \"args\": [\"/full/path/to/code-samples/ch16/clinic_server.py\"]\n    }\n  }\n}\n","ch16/client_stdio.py":"\"\"\"An MCP client: start the server as a subprocess and talk to it over stdio.\n\nThis is what Claude Desktop, VS Code or Claude Code do for you when you add a server to their config.\n\nRun:  python client_stdio.py\n\"\"\"\nimport asyncio\nimport json\nimport sys\nfrom pathlib import Path\n\nfrom mcp import ClientSession, StdioServerParameters\nfrom mcp.client.stdio import stdio_client\n\nSERVER = StdioServerParameters(command=sys.executable,\n                               args=[str(Path(__file__).with_name(\"clinic_server.py\"))])\n\n\nasync def main():\n    async with stdio_client(SERVER) as (read, write):          # 1. start the server process\n        async with ClientSession(read, write) as session:\n            info = await session.initialize()                    # 2. handshake: versions + capabilities\n            print(\"Connected to:\", info.serverInfo.name, \"| protocol\", info.protocolVersion)\n            print(\"Server offers:\", [k for k, v in info.capabilities.model_dump().items() if v])\n\n            tools = (await session.list_tools()).tools          # 3. discover\n            print(\"Tools:\", [t.name for t in tools])\n\n            result = await session.call_tool(\"get_doctor_schedule\", {\"department\": \"orthopaedics\"})   # 4. use\n            print(\"Result:\", json.loads(result.content[0].text))\n\n\nif __name__ == \"__main__\":\n    asyncio.run(main())\n","ch16/clinic_server.py":"\"\"\"A City Clinic MCP server: the Chapter 9 tools, offered to ANY MCP-compatible AI app.\n\nTools     = actions the model can call          (get_doctor_schedule, request_appointment)\nResources = data the app can read and attach    (clinic://doctors, clinic://policies/opd)\nPrompts   = reusable prompt templates for users (triage_message)\n\nRun:  python clinic_server.py            (stdio: the app starts this script and talks over stdin/stdout)\n      python clinic_server.py --http     (Streamable HTTP on http://127.0.0.1:8000/mcp)\nTest: npx @modelcontextprotocol/inspector python clinic_server.py\n\"\"\"\nimport logging\nimport sys\nfrom pathlib import Path\nfrom typing import Annotated\n\nHERE = Path(__file__).resolve().parent\nsys.path.insert(0, str(HERE.parent / \"ch09\"))\nimport clinic  # noqa: E402  (plain Python data and functions from Chapter 9)\nfrom mcp.server.fastmcp import FastMCP  # noqa: E402\nfrom mcp.types import ToolAnnotations  # noqa: E402\nfrom pydantic import Field  # noqa: E402\n\n# With stdio, stdout IS the protocol channel. Never print(); log to stderr instead.\nlogging.basicConfig(stream=sys.stderr, level=logging.WARNING)\nlog = logging.getLogger(\"clinic-mcp\")\nlog.setLevel(logging.INFO)\n\nmcp = FastMCP(\"City Clinic\", instructions=\"Doctor schedules and appointment requests for City Clinic. \"\n                                          \"Appointment requests always need staff approval.\")\nPOLICIES = HERE.parent / \"ch07\" / \"docs\"\n\n\n# ---------------------------------------------------------------- tools\n@mcp.tool(annotations=ToolAnnotations(readOnlyHint=True, openWorldHint=False))\ndef get_doctor_schedule(department: Annotated[str, Field(description=\"Department name, e.g. cardiology\")]) -> dict:\n    \"\"\"Look up which doctors in a hospital department see patients on which weekdays.\"\"\"\n    log.info(\"get_doctor_schedule department=%s\", department)\n    return clinic.get_doctor_schedule(department)\n\n\n@mcp.tool(annotations=ToolAnnotations(readOnlyHint=False, destructiveHint=False, idempotentHint=False))\ndef request_appointment(\n    doctor: Annotated[str, Field(description=\"Exact doctor name, e.g. Dr Rao\")],\n    day: Annotated[str, Field(description=\"Weekday, e.g. Thu\")],\n    patient_name: Annotated[str, Field(description=\"The patient's full name\", min_length=2)],\n) -> dict:\n    \"\"\"Create an appointment REQUEST for staff to approve. Only use it after the patient has asked to book\n    and given their name. It does not confirm the booking.\"\"\"\n    log.info(\"request_appointment doctor=%s day=%s\", doctor, day)      # no patient name in logs\n    return clinic.request_appointment(doctor, day, patient_name)\n\n\n# ---------------------------------------------------------------- resources\n@mcp.resource(\"clinic://doctors\", mime_type=\"application/json\")\ndef doctors() -> dict:\n    \"\"\"Every department, doctor and OPD day.\"\"\"\n    return clinic.SCHEDULE\n\n\n@mcp.resource(\"clinic://policies/{name}\", mime_type=\"text/markdown\")\ndef policy(name: str) -> str:\n    \"\"\"A clinic policy document: opd, visitors, insurance or emergency.\"\"\"\n    path = (POLICIES / f\"{name}.md\").resolve()\n    if path.parent != POLICIES.resolve() or not path.exists():     # block ../../etc/passwd tricks\n        raise ValueError(f\"No policy called '{name}'. Try: opd, visitors, insurance, emergency\")\n    return path.read_text(encoding=\"utf-8\")\n\n\n# ---------------------------------------------------------------- prompts\n@mcp.prompt(title=\"Triage a patient message\")\ndef triage_message(message: str) -> str:\n    \"\"\"Classify a patient message and draft a safe reply.\"\"\"\n    return (f\"Classify this City Clinic patient message as schedule, billing, emergency or other, then draft \"\n            f\"a short, safe reply. For emergencies say: go to Emergency or call 108.\\n\\nMessage: {message}\")\n\n\nif __name__ == \"__main__\":\n    mcp.run(transport=\"streamable-http\" if \"--http\" in sys.argv else \"stdio\")\n","ch16/mcp_agent_anthropic.py":"\"\"\"An agent whose tools come from an MCP server (Anthropic version).\n\nThe agent knows NOTHING about the clinic in advance: it discovers the tools from the server,\nconverts them to Anthropic's format, and runs the Chapter 9 loop, calling tools through MCP.\n\nRun:  python mcp_agent_anthropic.py \"Book Dr Rao on Thursday for Asha Verma\"\n\"\"\"\nimport asyncio\nimport json\nimport os\nimport sys\nfrom pathlib import Path\n\nfrom anthropic import AsyncAnthropic\nfrom dotenv import load_dotenv\nfrom mcp import ClientSession, StdioServerParameters\nfrom mcp.client.stdio import stdio_client\n\nload_dotenv()\nMODEL = os.getenv(\"ANTHROPIC_MODEL\", \"claude-haiku-5-5\")\nMAX_STEPS = 6\nSERVER = StdioServerParameters(command=sys.executable, args=[str(Path(__file__).with_name(\"clinic_server.py\"))])\nSYSTEM = \"You are the City Clinic helpdesk. Use the tools; never guess schedules. Keep replies short.\"\n\n\ndef to_anthropic(tool) -> dict:\n    \"\"\"MCP tool -> Anthropic tool spec. The MCP inputSchema is already JSON Schema.\"\"\"\n    return {\"name\": tool.name, \"description\": tool.description, \"input_schema\": tool.inputSchema}\n\n\ndef approved(tool, args) -> bool:\n    \"\"\"Tools not marked read-only need a person's OK (Chapter 9 harness rule).\"\"\"\n    if tool.annotations and tool.annotations.readOnlyHint:\n        return True\n    return input(f\"Allow {tool.name}({args})? [y/N] \").strip().lower() == \"y\"\n\n\nasync def run(question: str) -> str:\n    client = AsyncAnthropic(timeout=30, max_retries=2)\n    async with stdio_client(SERVER) as (read, write), ClientSession(read, write) as session:\n        await session.initialize()\n        mcp_tools = {t.name: t for t in (await session.list_tools()).tools}\n        messages = [{\"role\": \"user\", \"content\": question}]\n\n        for _ in range(MAX_STEPS):\n            reply = await client.messages.create(model=MODEL, max_tokens=800, system=SYSTEM, messages=messages,\n                                                 tools=[to_anthropic(t) for t in mcp_tools.values()])\n            if reply.stop_reason != \"tool_use\":\n                return \"\".join(b.text for b in reply.content if b.type == \"text\")\n            messages.append({\"role\": \"assistant\", \"content\": reply.content})\n            results = []\n            for block in reply.content:\n                if block.type != \"tool_use\":\n                    continue\n                tool = mcp_tools.get(block.name)\n                if tool is None:\n                    content, is_error = json.dumps({\"error\": f\"No tool called {block.name}\"}), True\n                elif not approved(tool, block.input):\n                    content, is_error = json.dumps({\"error\": \"A staff member declined this action.\"}), True\n                else:\n                    result = await session.call_tool(tool.name, block.input)  # runs on the MCP server\n                    content = \"\\n\".join(c.text for c in result.content if c.type == \"text\")\n                    is_error = result.isError\n                print(f\"  {block.name}({block.input}) -> {\" \".join(content.split())[:90]}\")\n                results.append({\"type\": \"tool_result\", \"tool_use_id\": block.id, \"content\": content, \"is_error\": is_error})\n            messages.append({\"role\": \"user\", \"content\": results})\n        return \"Sorry, I couldn't finish that. Please call the front desk: 1800-000-000.\"\n\n\nif __name__ == \"__main__\":\n    print(asyncio.run(run(\" \".join(sys.argv[1:]) or \"Which days does Dr Iyer work?\")))\n","ch16/mcp_agent_openai.py":"\"\"\"An agent whose tools come from an MCP server (OpenAI version).\n\nThe agent knows NOTHING about the clinic in advance: it discovers the tools from the server,\nconverts them to OpenAI's format, and runs the Chapter 9 loop, calling tools through MCP.\n\nRun:  python mcp_agent_openai.py \"Book Dr Rao on Thursday for Asha Verma\"\n\"\"\"\nimport asyncio\nimport json\nimport os\nimport sys\nfrom pathlib import Path\n\nfrom dotenv import load_dotenv\nfrom mcp import ClientSession, StdioServerParameters\nfrom mcp.client.stdio import stdio_client\nfrom openai import AsyncOpenAI\n\nload_dotenv()\nMODEL = os.getenv(\"OPENAI_MODEL\", \"gpt-4.1-mini\")\nMAX_STEPS = 6\nSERVER = StdioServerParameters(command=sys.executable, args=[str(Path(__file__).with_name(\"clinic_server.py\"))])\nSYSTEM = \"You are the City Clinic helpdesk. Use the tools; never guess schedules. Keep replies short.\"\n\n\ndef to_openai(tool) -> dict:\n    \"\"\"MCP tool -> OpenAI tool spec. The MCP inputSchema is already JSON Schema.\"\"\"\n    return {\"type\": \"function\", \"function\": {\"name\": tool.name, \"description\": tool.description,\n                                             \"parameters\": tool.inputSchema}}\n\n\ndef approved(tool, args) -> bool:\n    \"\"\"Tools not marked read-only need a person's OK (Chapter 9 harness rule).\"\"\"\n    if tool.annotations and tool.annotations.readOnlyHint:\n        return True\n    return input(f\"Allow {tool.name}({args})? [y/N] \").strip().lower() == \"y\"\n\n\nasync def run(question: str) -> str:\n    client = AsyncOpenAI(timeout=30, max_retries=2)\n    async with stdio_client(SERVER) as (read, write), ClientSession(read, write) as session:\n        await session.initialize()\n        mcp_tools = {t.name: t for t in (await session.list_tools()).tools}\n        messages = [{\"role\": \"system\", \"content\": SYSTEM}, {\"role\": \"user\", \"content\": question}]\n\n        for _ in range(MAX_STEPS):\n            reply = await client.chat.completions.create(\n                model=MODEL, messages=messages, tools=[to_openai(t) for t in mcp_tools.values()])\n            msg = reply.choices[0].message\n            if not msg.tool_calls:\n                return msg.content\n            messages.append(msg.model_dump(exclude_none=True))\n            for call in msg.tool_calls:\n                args = json.loads(call.function.arguments)\n                tool = mcp_tools.get(call.function.name)\n                if tool is None:\n                    content = json.dumps({\"error\": f\"No tool called {call.function.name}\"})\n                elif not approved(tool, args):\n                    content = json.dumps({\"error\": \"A staff member declined this action.\"})\n                else:\n                    result = await session.call_tool(tool.name, args)        # runs on the MCP server\n                    content = \"\\n\".join(c.text for c in result.content if c.type == \"text\")\n                print(f\"  {call.function.name}({args}) -> {\" \".join(content.split())[:90]}\")\n                messages.append({\"role\": \"tool\", \"tool_call_id\": call.id, \"content\": content})\n        return \"Sorry, I couldn't finish that. Please call the front desk: 1800-000-000.\"\n\n\nif __name__ == \"__main__\":\n    print(asyncio.run(run(\" \".join(sys.argv[1:]) or \"Which days does Dr Iyer work?\")))\n","ch16/test_server.py":"\"\"\"Talk to the server in memory, exactly as an MCP client would. No AI model involved.\n\nRun:  python test_server.py      (or: pytest test_server.py)\n\"\"\"\nimport asyncio\nimport json\n\nfrom clinic_server import mcp\nfrom mcp.shared.memory import create_connected_server_and_client_session\n\n\nasync def main():\n    async with create_connected_server_and_client_session(mcp) as client:\n        tools = await client.list_tools()\n        for t in tools.tools:\n            print(f\"tool     {t.name}  read-only={t.annotations.readOnlyHint}\")\n            print(f\"         input schema: {json.dumps(t.inputSchema['properties'])}\")\n\n        result = await client.call_tool(\"get_doctor_schedule\", {\"department\": \"cardiology\"})\n        print(\"call     ->\", json.dumps(json.loads(result.content[0].text)))\n\n        bad = await client.call_tool(\"request_appointment\", {\"doctor\": \"Dr Rao\", \"day\": \"Mon\", \"patient_name\": \"Asha\"})\n        print(\"call     ->\", json.dumps(json.loads(bad.content[0].text)))\n\n        invalid = await client.call_tool(\"request_appointment\", {\"doctor\": \"Dr Rao\", \"day\": \"Thu\"})\n        print(\"invalid  -> isError =\", invalid.isError, \"|\", invalid.content[0].text.splitlines()[0][:90])\n\n        res = await client.list_resources()\n        templates = await client.list_resource_templates()\n        print(\"resource \", [str(r.uri) for r in res.resources], [t.uriTemplate for t in templates.resourceTemplates])\n        opd = await client.read_resource(\"clinic://policies/opd\")\n        print(\"read     ->\", opd.contents[0].text.splitlines()[0])\n\n        prompt = await client.get_prompt(\"triage_message\", {\"message\": \"Is OPD open Sunday?\"})\n        print(\"prompt   ->\", prompt.messages[0].content.text[:70], \"...\")\n        return tools\n\n\ndef test_server():\n    tools = asyncio.run(main())\n    assert {t.name for t in tools.tools} == {\"get_doctor_schedule\", \"request_appointment\"}\n\n\nif __name__ == \"__main__\":\n    asyncio.run(main())\n","ch16/vscode_mcp.json":"{\n  \"servers\": {\n    \"city-clinic\": {\n      \"type\": \"stdio\",\n      \"command\": \"${workspaceFolder}/.venv/bin/python\",\n      \"args\": [\"${workspaceFolder}/code-samples/ch16/clinic_server.py\"]\n    },\n    \"city-clinic-remote\": {\n      \"type\": \"http\",\n      \"url\": \"http://127.0.0.1:8000/mcp\"\n    }\n  }\n}\n","common/requirements.txt":"# Pinned versions the course code was tested with. Install with: pip install -r requirements.txt\nopenai==3.43.0\nanthropic==2.4.0\npython-dotenv>=1.0\npydantic==2.13.5\ntiktoken>=0.8            # Chapter 2\nfastapi==0.162.0         # Chapter 5\nuvicorn>=0.30\npython-multipart>=0.0.9\nhttpx>=0.27\nstreamlit==1.66.1\ngradio==6.31.0\npytest>=8\n\n# Part C: frameworks and protocols (tested versions)\nlangchain==1.4.8                 # Chapters 12-13\nlangchain-core==1.7.4\nlangchain-openai==1.7.3\nlangchain-anthropic==1.7.9\nlangchain-community==0.4.2\nlangchain-text-splitters==1.1.3\nlangchain-classic==1.0.8         # only for legacy examples (AgentExecutor, old retrievers)\nlanggraph==1.2.19                # Chapters 14-15\nlanggraph-checkpoint-sqlite==3.1.3\nmcp==1.30.0                      # Chapters 16-17\nlangchain-mcp-adapters==0.3.2\nnetworkx==3.7                    # Chapter 18 (GraphRAG)\nchromadb==1.5.9                  # Chapters 6, 18, 19\nagno==3.1.12                     # Chapter 19\n# Optional: langchain-tavily, wikipedia, langchain-experimental (Chapter 13 built-in tools)\n# DSPy (Chapter 20) goes in a separate environment: see ch20/requirements-dspy.txt\n\n# Part D: multi-agent\n# CrewAI (Chapter 24) and AutoGen (Chapter 25) need their own environments: ch24/requirements-crewai.txt, ch25/requirements-autogen.txt\na2a-sdk==1.3.0                   # Chapter 26 (agent interoperability)\nfastapi==0.162.0\nuvicorn==0.54.0\n"});
